import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"技术债务治理","description":"先分清债务的类型和价值，再决定是 opportunistically 顺手还、专项还，还是干脆别还，并把\\"不再新增\\"当作长期目标。","frontmatter":{"title":"技术债务治理","description":"先分清债务的类型和价值，再决定是 opportunistically 顺手还、专项还，还是干脆别还，并把\\"不再新增\\"当作长期目标。"},"headers":[],"relativePath":"engineering/tech-debt.md","filePath":"engineering/tech-debt.md","lastUpdated":1786271684000}'),p={name:"engineering/tech-debt.md"};function l(o,t,i,d,r,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="技术债务治理" tabindex="-1">技术债务治理 <a class="header-anchor" href="#技术债务治理" aria-label="Permalink to &quot;技术债务治理&quot;">​</a></h1><p>技术债是被滥用最多的概念之一。任何看着不顺眼的旧代码都被叫做&quot;技术债&quot;，于是&quot;还债&quot;变成了&quot;我想重写&quot;的借口，重写完发现新代码也很快变成下一轮债。治理技术债的前提，是先想清楚什么是债、什么不是，哪些债值得还、哪些债该让它继续存在。把这件事想明白，才不会陷入&quot;无止境重构却没产出业务价值&quot;的循环。</p><h2 id="什么是技术债-什么不是" tabindex="-1">什么是技术债，什么不是 <a class="header-anchor" href="#什么是技术债-什么不是" aria-label="Permalink to &quot;什么是技术债，什么不是&quot;">​</a></h2><p>技术债是<strong>为了短期收益而有意做出的、会在未来产生额外成本的工程取舍</strong>。关键词是&quot;取舍&quot;——它有当时的理由，也有未来的代价。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是技术债：</span></span>
<span class="line"><span>  - 只是代码写得丑，但没有影响任何东西</span></span>
<span class="line"><span>  - 旧技术栈但运行稳定、没人改</span></span>
<span class="line"><span>  - 你不喜欢但工作正常的实现</span></span>
<span class="line"><span></span></span>
<span class="line"><span>是技术债：</span></span>
<span class="line"><span>  - 为了赶上线跳过了抽象，现在每加个功能都要改十处</span></span>
<span class="line"><span>  - 没有测试，每次改动都提心吊胆</span></span>
<span class="line"><span>  - 共享数据库直连，导致无法独立部署</span></span></code></pre></div><blockquote><p>不是所有旧代码都是债。一个运行良好、没人需要改的老模块，哪怕风格过时，也不是债——它是已经还清的旧账。别为了&quot;看着不顺眼&quot;就去动它。</p></blockquote><h2 id="债的分类" tabindex="-1">债的分类 <a class="header-anchor" href="#债的分类" aria-label="Permalink to &quot;债的分类&quot;">​</a></h2><p>债不是铁板一块，类型不同，处理方式完全不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>类型</th><th>特征</th></tr></thead><tbody><tr><td>来源</td><td>有意债</td><td>当时权衡过的，有记录</td></tr><tr><td></td><td>无意债</td><td>当时不懂事留下的，没记录</td></tr><tr><td>可承受性</td><td>可承受债</td><td>偶尔难受，但不阻碍业务</td></tr><tr><td></td><td>不可承受债</td><td>每次改动都拖慢团队，频繁出 bug</td></tr><tr><td>性质</td><td>设计债</td><td>架构耦合、抽象缺失</td></tr><tr><td></td><td>测试债</td><td>没测试、测试不稳定</td></tr><tr><td></td><td>文档债</td><td>没人知道为什么这么写</td></tr><tr><td></td><td>依赖债</td><td>老旧、有漏洞、不再维护的依赖</td></tr></tbody></table><p>有意债要保留当时的记录（&quot;为什么这么做&quot;），未来还债时不会误判。无意债最危险——团队不知道它的存在，每次踩坑都像第一次发现。</p><h2 id="识别与记录-让隐性债显性化" tabindex="-1">识别与记录：让隐性债显性化 <a class="header-anchor" href="#识别与记录-让隐性债显性化" aria-label="Permalink to &quot;识别与记录：让隐性债显性化&quot;">​</a></h2><p>治理的第一步是让债被看见。隐性债是最有害的，它存在于某个老员工的脑子里，人一走就失传。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>做法：</span></span>
<span class="line"><span>  - 遇到坑时，立刻在代码里留 TODO / 注释，说明问题和影响</span></span>
<span class="line"><span>  - 用 issue 跟踪，打上 tech-debt 标签</span></span>
<span class="line"><span>  - 标注&quot;影响什么&quot;（每次改动多花 X 小时 / 偶发故障 / 阻碍某个功能）</span></span></code></pre></div><p>记录的重点不是&quot;这里很烂&quot;，而是&quot;<strong>它造成了什么具体成本</strong>&quot;。没有具体成本的&quot;烂代码&quot;不构成债，不值得投入。</p><h2 id="偿还策略-不是所有债都要还" tabindex="-1">偿还策略：不是所有债都要还 <a class="header-anchor" href="#偿还策略-不是所有债都要还" aria-label="Permalink to &quot;偿还策略：不是所有债都要还&quot;">​</a></h2><p>这是治理中最关键的判断。债像金融债务一样，有的该尽快还，有的可以一直背着：</p><table tabindex="0"><thead><tr><th>债的特征</th><th>策略</th></tr></thead><tbody><tr><td>频繁出事、每次改动都拖慢</td><td>专项偿还，优先级高</td></tr><tr><td>偶尔难受但能绕过</td><td>维持，记录下来，等机会顺手改</td></tr><tr><td>有安全漏洞的依赖债</td><td>立刻还，不能拖</td></tr><tr><td>没人再碰的老模块</td><td>别还，让它自然淘汰</td></tr></tbody></table><p>两种主流偿还节奏：</p><ul><li><strong>Opportunistically（顺手还）</strong>：在改动某块代码时，把路过的相关债务一起清理。&quot;童子军法则&quot;——离开时比来时更干净。适合小规模、可承受债。</li><li><strong>专项偿还</strong>：对阻碍业务的不可承受债，立项集中投入。适合大债，但要明确目标和完成标准。</li></ul><blockquote><p>重写整个系统几乎从来不是好策略。重写的成本和风险巨大，而且重写过程中老系统还在出业务价值，团队往往陷入&quot;新老并行、两头都维护不动&quot;的泥潭。<strong>绝大多数债，应当通过渐进式重构逐步偿还</strong>。</p></blockquote><h2 id="防止新增-还的同时别再欠" tabindex="-1">防止新增：还的同时别再欠 <a class="header-anchor" href="#防止新增-还的同时别再欠" aria-label="Permalink to &quot;防止新增：还的同时别再欠&quot;">​</a></h2><p>只还旧债不防新债，等于一边倒水一边漏水。防止新增比偿还更重要：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机制：</span></span>
<span class="line"><span>  - Code Review 时识别新增的债，要求留 TODO 和 issue</span></span>
<span class="line"><span>  - 有意债要记录&quot;为什么、什么时候还&quot;</span></span>
<span class="line"><span>  - 关键模块加架构约束（依赖方向、分层规则），CI 校验</span></span>
<span class="line"><span>  - 给新人讲清楚架构约定，避免无意债</span></span></code></pre></div><p>有意债不是问题，<strong>没有记录的有意债才是问题</strong>。今天的取舍，要写得让三个月后的自己看得懂。</p><h2 id="与业务沟通" tabindex="-1">与业务沟通 <a class="header-anchor" href="#与业务沟通" aria-label="Permalink to &quot;与业务沟通&quot;">​</a></h2><p>技术债治理最大的障碍，是业务方听不懂&quot;我们要花两个月还技术债&quot;。换个说法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误沟通：</span></span>
<span class="line"><span>  &quot;我们要停下来重构，还技术债&quot;</span></span>
<span class="line"><span>  → 业务：然后呢？不交付功能了？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确沟通：</span></span>
<span class="line"><span>  &quot;现在每次加功能都要多花 3 天绕过这段代码，</span></span>
<span class="line"><span>   重构后能降到半天。两个月内省回来的工时，</span></span>
<span class="line"><span>   够我们多交付 X 个功能。&quot;</span></span></code></pre></div><p>把债翻译成业务能理解的语言：<strong>速度、稳定性、风险</strong>。还债的正当性来自它对未来交付速度的提升，而不是&quot;代码该干净&quot;这种审美诉求。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>你说的&quot;技术债&quot;是否真的造成了具体成本，还是只是看着不顺眼？</li><li>有意债是否留下了当时的记录，未来不会误判？</li><li>债是否被显性跟踪（issue / 标签），而不是存在于某人脑子里？</li><li>是否区分了&quot;该专项还的大债&quot;和&quot;该顺手还的小债&quot;？</li><li>是否在防新增（Review、架构约束），而不只是还旧的？</li><li>与业务沟通时，是否把债翻译成了交付速度和风险，而不是技术审美？</li></ul>`,30)])])}const q=a(p,[["render",l]]);export{h as __pageData,q as default};
